"""Create a standalone interactive coverage review from measured audit outputs."""
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parent
OUT = ROOT / "output"
data = {"chile":json.loads((OUT/"chile-quality.json").read_text(encoding="utf-8")),
        "mmdh":json.loads((OUT/"mmdh-quality.json").read_text(encoding="utf-8")),
        "jeju":json.loads((OUT/"jeju-sites.json").read_text(encoding="utf-8")),
        "sources":json.loads((ROOT/"sources.json").read_text(encoding="utf-8"))["sources"]}
# The public review carries factual catalog labels, not republished source descriptions/images.
data["jeju"]["records"] = [{"title":r["title"], "raw_fields":{"category":r["raw_fields"]["category"]}} for r in data["jeju"]["records"]]
payload = json.dumps(data,ensure_ascii=False).replace("<","\\u003c")
template = r'''<!doctype html><html lang="ko"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>아카이브 수집 · 자료 범위 점검</title>
<style>
:root{--ink:#102c39;--teal:#117b72;--gold:#c08a3e;--paper:#f5f2e9;--muted:#596e73;--line:#d9dfd9}*{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--ink);font:16px/1.65 'Malgun Gothic',sans-serif}header{background:var(--ink);color:white;padding:38px max(calc((100vw - 1180px)/2),30px)}header .kicker{font-size:13px;letter-spacing:2px;color:#efc57f}h1{font-size:38px;line-height:1.35;margin:12px 0}header p{max-width:900px;color:#c0d1d5;margin:10px 0}main{max-width:1240px;padding:30px;margin:auto}.cards{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}.card,.panel{background:#fff;padding:24px;border:1px solid var(--line)}.card b{display:block;font:700 40px/1.3 Georgia,serif;margin:8px 0}.card small{color:var(--muted)}.eyebrow{font-size:12px;letter-spacing:1px;font-weight:bold;color:var(--teal)}.notice{padding:14px 20px;border-left:3px solid var(--gold);background:#eee9dc;margin:22px 0}h2{margin:0 0 10px;font-size:22px}h3{font-size:17px;margin:20px 0 8px}.muted,.note{color:var(--muted)}.note{font-size:13px}section{margin-top:26px}.toolbar{display:flex;flex-wrap:wrap;align-items:center;gap:10px;margin:16px 0}button,select{font:inherit;color:var(--ink);background:white;border:1px solid #a9b8b7;padding:9px 13px;border-radius:3px;cursor:pointer}button[aria-pressed=true]{background:var(--ink);color:white}button:focus-visible,a:focus-visible{outline:3px solid var(--gold)}.legend{display:flex;gap:24px;font-size:13px}.swatch{display:inline-block;width:10px;height:10px;margin-right:7px}.chart{width:100%;display:block;min-height:260px}.chart text{font-family:'Malgun Gothic',sans-serif;fill:var(--muted);font-size:12px}.chart .bar{cursor:pointer}.chart .bar:hover{opacity:.7}#year-detail{background:#f0f5f2;padding:14px 18px;min-height:58px}.two{display:grid;grid-template-columns:1fr 1fr;gap:22px}.region-row{display:grid;grid-template-columns:145px 1fr 48px;gap:10px;align-items:center;margin:12px 0;font-size:13px}.track{height:12px;background:#edf0ec}.track i{height:100%;display:block;background:var(--teal)}.flow{display:grid;grid-template-columns:2fr 1fr;gap:12px}.big{font-size:28px;font-weight:700}.flow>div{padding:14px;border:1px solid var(--line)}.unit{font-size:12px;color:var(--muted)}table{width:100%;border-collapse:collapse;font-size:14px}td,th{text-align:left;border-bottom:1px solid var(--line);padding:12px 8px;vertical-align:top}th{font-size:12px;color:var(--muted)}a{color:var(--teal)}.sites{display:grid;grid-template-columns:repeat(3,1fr);gap:10px;margin-top:15px}.site{padding:14px;background:#f3f5f0;font-size:14px}.site small{display:block;color:var(--muted)}footer{font-size:12px;color:var(--muted);margin:30px 0}details{padding:12px 0}summary{cursor:pointer;font-weight:700}@media(max-width:800px){.cards,.two{grid-template-columns:1fr}.sites{grid-template-columns:1fr 1fr}h1{font-size:30px}main{padding:18px}.region-row{grid-template-columns:135px 1fr 44px}table{font-size:12px}}
</style>
<header><div class="kicker">TRC · ARCHIVE INGESTION PILOT · 2026.11.06</div><h1>자료가 모인 곳,<br>비어 있는 곳을 함께 봅니다</h1><p>칠레의 1973년 집중과 산티아고 편중을 검토하기 위해, 기존 입력 자료와 새 아카이브 목록을 실제로 수집·대조했습니다.</p></header>
<main><div class="cards"><div class="card"><div class="eyebrow">칠레 · 연구 데이터</div><b>2,398</b><div>Freire 외(2019)의 인물 기록</div><small>59개 원본 변수 · 모든 기록 보존</small></div><div class="card"><div class="eyebrow">칠레 · 박물관 공개 목록</div><b>3,216</b><div>MMDH 엑셀 내보내기</div><small>사망·강제실종 기록 · 2026.11.06 수집</small></div><div class="card"><div class="eyebrow">제주 · 공개 유적 목록</div><b>47곳</b><div>공식 아카이브 지역별 유적</div><small>평화재단 소개 25곳은 별도 출처 · 희생자 수 아님</small></div></div>
<div class="notice"><b>출처가 다른 명부는 겹칩니다.</b> 2,398명과 3,216명을 더해 총 희생자 수로 계산하지 않습니다. 인물·사건·장소·문서의 집계 단위를 구분합니다.</div>
<section class="panel"><h2>1973년에 집중된 현상은 원자료에도 있습니다</h2><p class="note">일·월·연도 중 알려진 범위로 연도를 집계했습니다. 막대를 누르면 출처별 수와 결측치를 확인할 수 있습니다.</p><div class="toolbar"><button id="count" aria-pressed="true">기록 수</button><button id="ratio" aria-pressed="false">출처 전체 대비 비율</button></div><div class="legend"><span><i class="swatch" style="background:var(--teal)"></i>Freire 외</span><span><i class="swatch" style="background:var(--gold)"></i>MMDH</span></div><div id="timeline"></div><div id="year-detail" aria-live="polite"></div><p class="note">두 자료군은 포함 범위·작성 시점이 다릅니다. 격차를 새로 발생한 피해의 수로 해석할 수 없습니다. MMDH의 1991년 표기 1건과 해석되지 않은 날짜 1건은 원문 재검토 대상입니다.</p></section>
<section class="two"><div class="panel"><h2>산티아고에만 있는 것은 아닙니다</h2><p class="note">MMDH가 제공한 지역 표기입니다. RM은 수도권이며 산티아고 시와 동일하지 않습니다. 대소문자만 다른 RM 두 표기는 아래에서 합쳐 표시했습니다.</p><div id="regions"></div><details><summary>원문 지역 표기 보기</summary><div id="raw-regions" class="note"></div></details></div><div class="panel"><h2>좌표 없는 기록도 DB에 남깁니다</h2><p class="note">Freire 자료 2,398명의 좌표 보유 범위</p><div class="flow"><div><span class="big">2,109명</span><div>첫 장소 좌표 있음</div></div><div><span class="big">289명</span><div>첫 장소 좌표 없음</div></div></div><div class="flow" style="margin-top:12px"><div><span class="big">117명</span><div>다른 장소 좌표는 있음</div></div><div><span class="big">172명</span><div>어느 장소도 좌표 없음</div></div></div><p>기존 수집기는 첫 장소의 좌표가 없으면 기록 전체를 제외했습니다. 새 구조는 최대 6개 장소를 각각 보존합니다.</p><h3>겹친 점 하나 안에 265개 기록</h3><p class="note">산티아고 대표 좌표 (-33.44889, -70.66927)에 첫 장소 기록 265개가 겹칩니다. 지도에서는 건수와 근사 좌표 여부를 표시해야 합니다. 점을 임의로 흩어 정확한 위치처럼 보여주지 않습니다.</p><h3>날짜의 정밀도도 자료입니다</h3><div id="date-precision" class="note"></div></div></section>
<section class="panel"><h2>제주는 명부·피해조사·유적을 연결합니다</h2><p>공식 아카이브의 지역별 공개 유적 47곳과 평화재단 소개 유적 25곳을 출처별로 수집해 운영 지도에 연결했습니다. 아래 목록은 평화재단 소개 25곳입니다. 유적 목록에 등장하는 연도를 일괄 사건일로 바꾸거나, 유적 한 곳을 희생자 한 명으로 계산하지 않습니다.</p><div class="toolbar"><label for="site-region">원문 지역 분류</label><select id="site-region"><option value="all">전체</option></select><span id="site-count" class="note"></span></div><div id="sites" class="sites"></div><p class="note">지역 분류도 검증 대상입니다. 예를 들어 원문은 북촌국민학교를 ‘제주시’로 분류합니다. 원문 표기는 보존하고, 정정한 행정구역은 별도 근거와 함께 추가해야 합니다.</p></section>
<section class="panel"><h2>확장할 아카이브와 수집 방식</h2><table><thead><tr><th>우선순위</th><th>아카이브</th><th>수집 단위와 방법</th></tr></thead><tbody id="source-table"></tbody></table></section>
<section class="panel"><h2>다음 데이터가 화면으로 이어지는 경로</h2><p><b>원본 보존 → 표·본문 추출 → 날짜·지명 정규화 → 인물·사건 연결 검토 → SQL 적재 → 지도·연표·분포</b></p><p class="note">파일 해시·수집 시각·출처 내 위치·파서 버전을 남깁니다. 원문과 정규화 값을 함께 보존합니다. 보고서 쪽수와 피해자 명부의 연결, OCR 오독, 동명이인, 행정구역 변동은 검수 대기 항목으로 관리합니다.</p></section>
<footer>Oracle 시험 적재·반복 실행 검증 후 네 자료군을 운영 지도에 연결했습니다. 기존 사건 테이블의 2,116개 기록도 보존합니다. 이 화면은 수집·정규화 파일의 검토본이며, 역사적 사실관계의 최종 확정본이 아닙니다.</footer></main>
<script id="dataset" type="application/json">__PAYLOAD__</script><script>
const D=JSON.parse(document.getElementById('dataset').textContent),fmt=n=>Number(n).toLocaleString('ko-KR'),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));let mode='count';
function detail(year){const a=D.chile.annual.find(x=>x.year===year)?.all_known_year||0,b=D.mmdh.annual[year]||0;document.getElementById('year-detail').textContent=`${year}년 · Freire ${fmt(a)}건 (${(a/2398*100).toFixed(1)}%) / MMDH ${fmt(b)}건 (${(b/3216*100).toFixed(1)}%). 연도 미상: Freire 109건, MMDH 1건.`;}
function chart(){let years=Array.from({length:19},(_,i)=>1973+i),rows=years.map(y=>[y,D.chile.annual.find(x=>x.year===y)?.all_known_year||0,D.mmdh.annual[y]||0]),W=1100,H=320,L=55,T=20,B=45,PW=W-L-15,PH=H-T-B,slot=PW/19,val=(n,i)=>mode==='count'?n:n/(i===1?2398:3216)*100,max=mode==='count'?2000:60;
let s=`<svg class="chart" viewBox="0 0 ${W} ${H}" role="group" aria-label="출처별 연도 분포">`;for(let i=0;i<=4;i++){let v=max*i/4,y=T+PH*(1-i/4);s+=`<line x1="${L}" x2="${W-15}" y1="${y}" y2="${y}" stroke="#dde3dc"/><text x="${L-8}" y="${y+4}" text-anchor="end">${fmt(v)}${mode==='ratio'?'%':''}</text>`;}for(let j=0;j<rows.length;j++){let r=rows[j],x=L+j*slot;for(let i=1;i<=2;i++){let h=val(r[i],i)/max*PH;s+=`<rect class="bar" role="button" tabindex="0" aria-label="${r[0]}년 ${i===1?'Freire':'MMDH'} ${r[i]}건" data-year="${r[0]}" x="${x+(i===1?.13:.51)*slot}" y="${T+PH-h}" width="${slot*.34}" height="${Math.max(h,2)}" fill="${i===1?'#117b72':'#c08a3e'}"><title>${r[0]}년 ${fmt(r[i])}건</title></rect>`;}s+=`<text x="${x+slot*.5}" y="${H-15}" text-anchor="middle">${String(r[0]).slice(2)}</text>`;}s+='</svg>';document.getElementById('timeline').innerHTML=s;document.querySelectorAll('[data-year]').forEach(e=>{e.onclick=()=>detail(+e.dataset.year);e.onkeydown=v=>{if(v.key==='Enter'||v.key===' '){v.preventDefault();detail(+e.dataset.year);}};});}
for(const id of ['count','ratio'])document.getElementById(id).onclick=()=>{mode=id;for(const b of ['count','ratio'])document.getElementById(b).setAttribute('aria-pressed',String(id===b));chart();};chart();detail(1973);
let groups={};for(const [k,n] of Object.entries(D.mmdh.source_region_labels)){let label=k.toUpperCase()==='RM METROPOLITANA'?'RM Metropolitana (표기 통합)':k;groups[label]=(groups[label]||0)+n;}document.getElementById('regions').innerHTML=Object.entries(groups).sort((a,b)=>b[1]-a[1]).slice(0,8).map(([k,n])=>`<div class="region-row"><span>${esc(k)}</span><span class="track"><i style="width:${n/1937*100}%"></i></span><b>${fmt(n)}</b></div>`).join('');document.getElementById('raw-regions').innerHTML=Object.entries(D.mmdh.source_region_labels).map(([k,n])=>`${esc(k)}: ${fmt(n)}건`).join('<br>');
document.getElementById('date-precision').textContent='Freire: 일 단위 2,232건 · 월 단위 57건 · 미상 109건. MMDH: 일 단위 3,123건 · 월 단위 89건 · 연 단위 3건 · 검토 1건.';
let items=D.jeju.records;for(const region of [...new Set(items.map(r=>r.raw_fields.category))]){let e=document.createElement('option');e.value=region;e.textContent=region;document.getElementById('site-region').append(e);}function sites(){let region=document.getElementById('site-region').value,selected=items.filter(r=>region==='all'||r.raw_fields.category===region);document.getElementById('site-count').textContent=`${selected.length}곳 · 소개 목록 기준`;document.getElementById('sites').innerHTML=selected.map(r=>`<div class="site"><small>${esc(r.raw_fields.category)}</small><b>${esc(r.title)}</b></div>`).join('');}document.getElementById('site-region').onchange=sites;sites();
document.getElementById('source-table').innerHTML=D.sources.map(s=>`<tr><td>${s.priority}</td><td><a href="${esc(s.url)}" target="_blank" rel="noopener">${esc(s.title)} ↗</a></td><td>${esc(s.scope)}</td></tr>`).join('');
</script></html>'''
(OUT/"coverage-review.html").write_text(template.replace("__PAYLOAD__",payload),encoding="utf-8")
print(OUT/"coverage-review.html")
